    (E bs fb tot : Z) (m : mem) (mw1 : cell) : machine_state -> Prop :=
  fun ms' => exists m',
       ms' = rs_ms P_A_STREAM_READ_SOME (Z_to_bv 64 RS_RSRET) sp gp tp t0 t1 t2 (wz (E + 8)) E
                   (wz bs) (wz (bv_unsigned sp + -120)) (wz E) a3 a4 a5 a6 a7 tot fb (wz (E + 8)) (wz (E + 16)) s9x t3 t4 t5 t6 F fc m'
    /\ munch [(bv_unsigned sp + -168, bv_unsigned sp + -160)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (bv_unsigned sp + -176) [mw1; C8 (wz (Z.shiftr (E + 16) 3 + 2147450880))].

Lemma rs_afterdbp : forall rax sp gp tp t0 t1 t2 s0x a0 a1 a2 a3 a4 a5 a6 a7 s9x t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo E bs fb P tot n : Z) (mw1 mw2 : cell) (t2c : list cell) (oj7 : list byte) (outp : Z),
