  rw_cells asegs m E (ErrCodeCells EC_clear) -> aapp E 24 -> accessible m E 24 -> E mod 8 = 0 ->
  0 <= bs < 2^64 -> lo <= bv_unsigned sp + -208 -> aceil <= lo ->
  mem_inv asegs m ->
